<?php
require 'config/auth.php';require 'config/db.php';require 'config/ledger.php';require 'config/reporting_35.php';require_permission('budget.view');
$id=(int)($_GET['id']??0);$q=$conn->prepare('SELECT * FROM control_accounts WHERE id=?');$q->bind_param('i',$id);$q->execute();$account=$q->get_result()->fetch_assoc();
if(!$account||!can_access_unit((int)$account['unit_id'])){http_response_code(403);exit('ไม่พบบัญชีคุมที่มีสิทธิ์เข้าถึง');}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST')try {
 require_permission('budget.edit');if(!organization_ready($conn))throw new DomainException('ต้องติดตั้งตาราง v8 ก่อน');begin_financial_transaction($conn);
 if(($_POST['action']??'')==='classify') {
  $account=ledger_account($conn,$id,true);if(classification_get($conn,$id))throw new DomainException('บัญชีนี้จำแนกแล้ว ข้อมูล ณ วันสร้างจะเก็บไว้เพื่อรักษารายงาน');
  $lock=$conn->prepare('CALL rpbs_assert_open(?,?,NULL)');$lock->bind_param('ii',$account['unit_id'],$account['fiscal_year']);$lock->execute();$lock->close();while($conn->more_results()&&$conn->next_result())if($result=$conn->store_result())$result->free();
  $v=classification_validate($conn,$_POST,(int)$account['unit_id']);classification_store($conn,$id,$v);
 }elseif(($_POST['action']??'')==='plans')report_plan_save($conn,$id,$_POST['plans']??[]);
 else throw new DomainException('รายการไม่ถูกต้อง');$conn->commit();header('Location: budget_classification.php?id='.$id.'&saved=1');exit;
}catch(Throwable $e){$conn->rollback();$error=operation_error($e);}
$classification=classification_get($conn,$id);$plans=[];if(organization_ready($conn)){$q=$conn->prepare('SELECT * FROM budget_quarter_plans WHERE control_account_id=?');$q->bind_param('i',$id);$q->execute();foreach($q->get_result() as $p)$plans[(int)$p['quarter_no']]=$p;}
?>
<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ข้อมูลจำแนกและแผนรายไตรมาส | 35MDBS</title><link rel="stylesheet" href="assets/css/style.css?v=<?=filemtime(__DIR__.'/assets/css/style.css')?>"></head><body><?php require 'template/nav.php';?><main class="container"><section class="panel"><h1 class="page-title"><?=htmlspecialchars($account['budget_code'])?> · ข้อมูลจำแนกและแผน</h1><p><?=htmlspecialchars($account['item_name'])?> · ปีงบประมาณ <?=(int)$account['fiscal_year']?></p><a class="btn btn-outline" href="control_account_detail.php?id=<?=$id?>">กลับบัญชีคุม</a></section><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="alert alert-success">บันทึกเรียบร้อย</div><?php endif;?>
<?php if($classification):?><section class="panel"><h2>ข้อมูล ณ วันที่จำแนกบัญชีคุมงบประมาณ</h2><dl class="classification-details"><?php foreach(['main_unit'=>'หน่วยหลัก','sub_unit'=>'หน่วยย่อย','secondary_unit'=>'หน่วยรอง','cost_center'=>'ศูนย์ต้นทุน','strategy_no'=>'ยุทธศาสตร์ที่','strategy_name'=>'ยุทธศาสตร์','plan_name'=>'แผนงาน','activity_name'=>'กิจกรรม','work_group'=>'กลุ่มงบงาน','project_name'=>'งบงานย่อย / โครงการ','expense_code'=>'หมวดเงิน','expense_name'=>'ชื่อหมวดเงิน'] as $k=>$label):?><div><dt><?=$label?></dt><dd><?=htmlspecialchars((string)($classification[$k]??''))?></dd></div><?php endforeach;?></dl></section><?php elseif(has_permission('budget.edit')):?><form method="post"><?=csrf_field()?><?=request_field()?><input type="hidden" name="action" value="classify"><?php require 'config/classification_form.php';?><section class="panel"><p>สำหรับบัญชีคุมงบประมาณเดิม: ต้องเลือกหน่วยย่อยเดิมของบัญชีนี้ ระบบไม่ย้ายยอดเงินหรือเปลี่ยนเจ้าของงบประมาณ</p><button class="btn btn-primary">บันทึกการจำแนกบัญชีคุมงบประมาณเดิม</button></section></form><?php endif;?>
<?php if(organization_ready($conn)&&has_permission('budget.edit')):?><section class="panel"><h2>แผน / ผลการปฏิบัติงานและแผนการใช้จ่าย</h2><p>แผนกรอกโดยเจ้าหน้าที่ ไม่ใช้ยอดเงินรับแทนแผน ส่วนผลการตัดจ่ายดึงจากบัญชีคุมโดยตรง ไตรมาส 1 = ต.ค.–ธ.ค.</p><form method="post"><?=csrf_field()?><?=request_field()?><input type="hidden" name="action" value="plans"><div class="table-wrap"><table><tr><th>ไตรมาส</th><th>แผนผูกพัน (บาท)</th><th>แผนเบิกจ่าย (บาท)</th><th>หน่วยนับผลงาน</th><th>แผนผลงาน</th><th>ผลปฏิบัติงาน</th></tr><?php foreach(range(1,4) as $quarter):?><tr><td><?=$quarter?></td><?php foreach(['obligation_plan','payment_plan','output_unit','output_plan','output_actual'] as $key):?><td><input name="plans[<?=$quarter?>][<?=$key?>]" value="<?=htmlspecialchars((string)($plans[$quarter][$key]??''))?>" <?=$key==='output_unit'?'maxlength="50"':'type="number" min="0" step="0.01"'?>></td><?php endforeach;?></tr><?php endforeach;?></table></div><button class="btn btn-primary">บันทึกแผน / ผลงาน</button></form></section><?php endif;?></main><script src="assets/js/organization.js?v=<?=filemtime(__DIR__.'/assets/js/organization.js')?>" defer></script></body></html>
